script:
(function () {
  'use strict';
  // Certificate of deposit growth. Every rate is first turned into an annual percentage yield:
  //   APR compounded n times a year: APY = (1 + r/n)^n - 1;  continuous: APY = e^r - 1;
  //   rate entered as APY: used as is.
  // Balance after m months = deposit x (1 + APY)^(m/12), which equals deposit x (1 + r/n)^(n x m/12).
  // The nominal rate shown for an APY input is n x ((1 + APY)^(1/n) - 1) (continuous: ln(1 + APY)).
  // Tax: interest x (1 - marginal rate), assuming the interest is taxed as ordinary income.
  // Verified (scratchpad tests/cd.test.js): $10,000 at 5% compounded annually for 36 months =
  // $11,576.25; 5% monthly for 36 months = $11,614.72 (APY 5.116%); 5% daily for 12 months =
  // $10,512.67; 5% continuous for 12 months = $10,512.71; 4% APY for 18 months = $10,605.96;
  // 24% tax on the 36-month annual case leaves $1,197.95 of interest; 0% returns the deposit unchanged.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function pct(x) { return (x * 100).toFixed(3).replace(/0+$/, '').replace(/\.$/, '') + '%'; }

  function toApy(rate, n) { return n === 0 ? Math.exp(rate) - 1 : Math.pow(1 + rate / n, n) - 1; }
  function toNominal(apy, n) { return n === 0 ? Math.log(1 + apy) : n * (Math.pow(1 + apy, 1 / n) - 1); }

  function grow(deposit, apy, months) {
    var rows = [], prev = deposit;
    for (var m = 12; m < months + 12; m += 12) {
      var at = Math.min(m, months), bal = deposit * Math.pow(1 + apy, at / 12);
      rows.push({ month: at, interest: bal - prev, total: bal - deposit, balance: bal });
      prev = bal;
    }
    return { balance: deposit * Math.pow(1 + apy, months / 12), rows: rows };
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var deposit = num('cdDeposit'), rate = num('cdRate'), months = Math.round(num('cdTerm')),
        n = parseInt(document.getElementById('cdCompound').value, 10), type = document.getElementById('cdRateType').value,
        tax = num('cdTax');
    if (isNaN(tax)) tax = 0;
    var error = document.getElementById('cdError');
    var bad = [deposit, rate, months].some(isNaN) || deposit < 0 || rate < 0 || rate > 100 ||
              months < 1 || months > 600 || tax < 0 || tax > 100 || isNaN(n);
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a deposit of $0 or more, a rate from 0 to 100%, a term of 1 to 600 months and a tax rate from 0 to 100%.';
      ['cdBalance', 'cdInterest', 'cdRateOut', 'cdAfterTax'].forEach(function (id) { set(id, '–'); });
      document.getElementById('cdSchedule').innerHTML = '';
      return;
    }
    var apy, other;
    if (type === 'apy') {
      apy = rate / 100;
      other = toNominal(apy, n);
      set('cdRateOutLabel', 'Equivalent interest rate (APR)');
    } else {
      apy = toApy(rate / 100, n);
      other = apy;
      set('cdRateOutLabel', 'Annual percentage yield (APY)');
    }
    var g = grow(deposit, apy, months), interest = g.balance - deposit;
    set('cdBalance', money.format(g.balance));
    set('cdInterest', money.format(interest));
    set('cdRateOut', pct(other));
    set('cdAfterTax', money.format(interest * (1 - tax / 100)));
    set('cdAfterTaxNote', tax > 0 ? 'At a ' + tax + '% tax rate: ' + money.format(interest * tax / 100) + ' in tax.' : 'Add your tax rate under More options.');
    document.getElementById('cdSchedule').innerHTML = g.rows.map(function (row) {
      var label = row.month % 12 === 0 ? 'Year ' + row.month / 12 : 'Month ' + row.month;
      return '<tr><td>' + label + '</td><td>' + money.format(row.interest) + '</td><td>' +
             money.format(row.total) + '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cdForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
